function situation7(){if(v7.scene==='leave')return t('Hari ini kamu sedang cuti. Nikmati waktu istirahatmu.','You are on leave today. Enjoy your time off.');if(v7.scene==='holiday')return t('Hari ini hari libur. Berikut kondisi pekerjaan terakhir.','Today is a day off. Here is the latest work status.');const count=operationalTasks().filter(taskAttention).length+(me().super?data.ops.filter(x=>x.status!=='paid'&&opPriority(x)).length:0);return count?t(`${count} pekerjaan perlu perhatian. Mulai dari yang membutuhkan keputusanmu.`,`${count} items need attention. Start with those requiring your decision.`):t('Antrean sedang tenang. Lanjutkan pekerjaan yang masih berjalan.','The queue is calm. Continue work already in progress.');}
