dashboard=function(){const b=document.createElement('div');b.innerHTML=base7.dashboard();b.querySelector('.eyebrow')?.remove();b.querySelector('h1').textContent=greeting7();b.querySelector('.pagehead .sub').textContent=situation7();b.querySelector('.calm-banner')?.remove();b.querySelector('.dashboard-grid').hidden=false;b.querySelector('.analysis6')?.remove();const platform=b.querySelector('.platform6'),withdraw=platform.querySelector('.withdraw6');platform.querySelector(':scope>.spread')?.remove();if(withdraw){withdraw.remove();platform.insertAdjacentHTML('beforebegin',`<div class="finance-insight7">${withdraw.outerHTML}${insight7()}</div>`);}else platform.insertAdjacentHTML('beforebegin',insight7());platform.querySelectorAll('.compare6').forEach((e,i)=>{const d=platformData6.find(x=>x[0]===e.dataset.id);e.classList.add(d[3]>=d[4]?'up':'down');});const stats=b.querySelector('.task-stats6');stats.querySelector('h2').textContent=t('Statistik Pekerjaan','Work Statistics');stats.querySelector(':scope>small').textContent=t('Seluruh pekerjaan yang dapat dilihat akun ini','All work visible to this account');b.querySelector('.activity6').insertAdjacentHTML('beforebegin',volume7());b.querySelectorAll('.stat6').forEach(e=>{e.querySelector('i').textContent=v6.filter===e.dataset.id?'×':'↗';e.setAttribute('aria-expanded',String(v6.filter===e.dataset.id));});return b.innerHTML;};
function timeTable7(team=me().super){const rows=(team?people:[me()]).map(p=>({p,s:timeSummary(p.id,v7.attDate),a:base7.attendanceToday(p)})).filter(({p,s})=>p.name.toLowerCase().includes(v7.attSearch.toLowerCase())&&(v7.attFilter==='all'||v7.attFilter==='incomplete'&&!s.complete&&!p.super||v7.attFilter==='late'&&s.late>data.policy.grace&&!p.super));rows.sort((a,b)=>v7.attSort==='duration'?(b.s.span||0)-(a.s.span||0):v7.attSort==='arrival'?(clockMinutes(a.s.record?.in)??999)-(clockMinutes(b.s.record?.in)??999):a.p.name.localeCompare(b.p.name));return section7(t('Detail Kehadiran','Attendance Detail'),`<div class="table-controls7"><input id="att-search7" value="${esc(v7.attSearch)}" placeholder="${t('Cari nama…','Search names…')}" aria-label="${t('Cari nama','Search name')}"><input type="date" id="att-date7" value="${v7.attDate}" aria-label="${t('Tanggal','Date')}"><select id="att-filter7" aria-label="Filter"><option value="all">${t('Semua status','All statuses')}</option><option value="late" ${v7.attFilter==='late'?'selected':''}>${t('Terlambat','Late')}</option><option value="incomplete" ${v7.attFilter==='incomplete'?'selected':''}>${t('Belum lengkap','Incomplete')}</option></select><select id="att-sort7" aria-label="${t('Urutkan','Sort by')}">${[['name',t('Nama','Name')],['arrival',t('Jam masuk','Arrival')],['duration',t('Durasi','Duration')]].map(([v,l])=>`<option value="${v}" ${v7.attSort===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr>${[t('Nama','Name'),'Check-in','Check-out',t('Durasi','Duration'),t('Kehadiran','Attendance'),t('Evaluasi Waktu','Time Review')].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(({p,s})=>`<tr><td>${personCell(p)}</td><td>${s.record?.in||'—'}</td><td>${s.record?.out||'—'}</td><td>${s.complete?durationLabel(s.span):'—'}</td><td>${p.super?badge(t('Dikecualikan','Exempt')):badge(s.record?(s.late>data.policy.grace?t('Terlambat','Late'):t('Tepat waktu','On time')):t('Belum tercatat','Not recorded'),s.late>data.policy.grace?'amber':'')}</td><td>${p.super?t('Catatan kontribusi saja','Contribution records only'):!s.complete?badge(t('Belum lengkap','Incomplete'),'amber'):badge(s.diff===0?t('Durasi terpenuhi','Duration met'):(s.diff<0?t('Kurang ','Under '):t('Lebih ','Over '))+durationLabel(Math.abs(s.diff)),s.diff<0?'amber':'blue')}${!p.super?btn(t('Koreksi','Correct'),'v5-time-correct',`data-id="${p.id}" data-date="${v7.attDate}"`,'text'):''}</td></tr>`).join('')||`<tr><td colspan="6">${t('Tidak ada catatan yang cocok','No matching records')}</td></tr>`}</tbody></table></div><p class="scope-note">${t('8 jam termasuk istirahat 12.00–13.30. Kelebihan durasi tidak otomatis berarti lembur.','8 hours includes the 12:00–13:30 break. Extra duration is not automatically overtime.')}</p>`,'attendance7');}
const sampleTime7={adovi:{present:[8,8.3,8,7.5,8],active:[5.2,5.8,5.6,4.9,5.7]},cantika:{present:[8,8,8.2,8,6],active:[5.8,6.1,5.7,5.9,4.5]},jeck:{present:[7,8,7.5,8,8],active:[4,5,5.5,5,5.6]},eka:{present:[8,8,8,9,9],active:[5,5.5,5.6,6,6.2]}};
function personSelect7(){return `<select id="chart-staff7" aria-label="${t('Pilih staf','Choose staff')}">${people.map(p=>`<option value="${p.id}" ${v7.staff===p.id?'selected':''}>${p.name}</option>`).join('')}</select>`;}
function curve7(id){const s=sampleTime7[id]||sampleTime7.adovi,a=weeklyValues7(id),record=timeSummary(id);const total=a.reduce((x,y)=>x+(y||0),0),act=s.active.filter((_,i)=>weeklyValues7(id)[i]!=null).reduce((x,y)=>x+y,0),pts=v=>v.map((n,i)=>n==null?'':`${35+i*125},${180-n*15}`).filter(Boolean).join(' ');return section7(t('Kehadiran & Aktivitas Tercatat','Attendance & Recorded Activity'),`${me().super?personSelect7():''}<div class="curve-metrics"><strong>${n7(total)} <small>${t('jam hadir','hours present')}</small></strong><strong>${n7(act)} <small>${t('jam aktivitas contoh','sample activity hours')}</small></strong>${badge(n7(total?act/total*100:0)+'% '+t('tercatat','recorded'),'blue')}</div><svg class="curve7" viewBox="0 0 570 210" role="img" aria-label="${t('Grafik waktu Senin sampai Jumat, data simulasi','Monday to Friday time chart, simulated data')}"><path d="M35 30H540M35 90H540M35 150H540" stroke="var(--line)"/><polyline points="${pts(a)}" stroke="var(--muted)"/><polyline points="${pts(s.active.map((v,i)=>weeklyValues7(id)[i]==null?null:v))}" stroke="var(--accent)"/>${t('Sen Sel Rab Kam Jum','Mon Tue Wed Thu Fri').split(' ').map((x,i)=>`<text x="${35+i*125}" y="205">${x}</text>`).join('')}</svg><div class="legend"><span>● ${t('Hadir','Present')}</span><span style="color:var(--accent)">● ${t('Aktivitas tercatat','Recorded activity')}</span></div><p class="scope-note">${t('14–18 September · catatan belum lengkap dikecualikan; contoh sesi, bukan pengukuran produktivitas. Aktivitas di luar web belum seluruhnya tercakup. Koreksi Jumat memperbarui kurva hadir.','September 14–18 · incomplete records excluded; sample sessions, not a productivity measurement. Off-site work is not fully covered. Friday corrections update attendance.')}</p>${btn(t('Dasar perhitungan','Calculation details'),'v7-time-basis','','text')}`);}
function kpi7(team=false){const ids=team?people.filter(p=>!p.super).map(p=>p.id):[me().super?v7.staff:me().id],ms=ids.map(id=>perf(id)),eligible=ms.filter(m=>m.total),quality=eligible.length?eligible.reduce((s,m)=>s+100*(m.total-m.corrections)/m.total,0)/eligible.length:0,timely=eligible.length?eligible.reduce((s,m)=>s+100*m.on/m.total,0)/eligible.length:0,score=(quality*v7.kpiQuality+timely*(100-v7.kpiQuality))/100;return section7(team?t('Rata-rata KPI Tim','Average Team KPI'):t('Panel KPI','KPI Panel'),`<span class="badge blue">${t('Simulasi · belum menjadi standar','Simulation · not an active standard')}</span><div class="kpi-number">${eligible.length?n7(score):'—'}<small>/100</small></div><p>${eligible.length} ${t('staf dengan bukti periode ini','staff with evidence this period')} · ${month()}</p><div class="kpi-bars">${[[t('Kualitas tercatat','Recorded quality'),quality],[t('Ketepatan tindak lanjut','Timely follow-up'),timely]].map(([l,v])=>`<div><span>${l}</span><b>${n7(v)}%</b>${progress(v)}</div>`).join('')}</div><p class="scope-note">${t('Kualitas dihitung dari hasil tanpa koreksi internal tercatat. Tidak ada ranking; bobot belum disahkan.','Quality reflects outcomes without recorded internal correction. No rankings; weights are not approved.')}</p>${me().super?`<label>${t('Uji bobot kualitas','Try quality weight')}: ${v7.kpiQuality}%<input id="kpi-weight7" type="range" min="0" max="100" step="5" value="${v7.kpiQuality}"></label><p class="notice">${v7.kpiQuality<50?t('Bobot kecepatan mendominasi. Periksa risiko kualitas sebelum menerapkan.','Timeliness dominates. Review quality risks before adopting.'):t('Kualitas mendapat perhatian lebih besar. Tetap tinjau kelengkapan bukti.','Quality receives more weight. Still review evidence coverage.')}</p>`:''}${btn(t('Lihat bukti & rumus','View evidence & formula'),'v7-kpi-basis','','text')}`,'kpi7');}
function tracker7(id=me().id){const r=timeSummary(id),elapsed=r.complete?r.span:Math.max(0,clockMinutes('14:00')-clockMinutes(r.record?.in||'14:00'))+Math.floor((Date.now()-v7.login)/60000);return section7(t('Waktu Kehadiran','Attendance Time'),`<div class="clock-ring7" style="--angle:${Math.min(360,elapsed/480*360)}deg"><div><strong id="live-time7">${durationLabel(elapsed)}</strong><small>${r.complete?t('Sesi selesai','Session complete'):t('Sejak masuk · simulasi','Since login · simulated')}</small></div></div><p>${r.complete?t('Catatan masuk dan pulang sudah lengkap.','Arrival and departure are complete.'):t('Sesi otomatis berjalan. Check-out belum tercatat.','Session runs automatically. Check-out is not recorded.')}</p><small>${t('Istirahat 12.00–13.30 termasuk 8 jam. Online tidak sama dengan bekerja.','12:00–13:30 break is included in 8 hours. Online does not mean working.')}</small>`,'tracker7');}
personalOverview=function(id){const p=person(id),m=perf(id);const task=data.tasks.filter(x=>x.handler===id&&x.stage!=='done'),done=todayRecords().filter(x=>x.staff===id).length;return pageHead(t('Halo, ','Hello, ')+p.name+'.','')+`<div class="personal7"><div class="personal-main7"><div class="personal-summary7">${[[Math.max(0,Math.floor((new Date(day())-new Date(p.joined))/86400000)),t('Hari bersama tim','Days with the team')],[m.total,t('Selesai periode ini','Completed this period')],[task.length,t('Dalam penanganan','In progress')]].map(([v,l])=>`<div><strong>${v}</strong><span>${l}</span></div>`).join('')}</div><div class="personal-widgets7">${section7(t('Pekerjaan Hari Ini','Today’s Work'),`<div class="spread"><strong>${done} ${t('selesai','completed')}</strong><span>${task.length} ${t('berjalan','ongoing')}</span></div><div class="stacked-work7">${task.slice(0,3).map(x=>`<button data-action="task" data-id="${x.id}"><span>${esc(splitLabel(x.title))}<small>${stageName(x.stage)}</small></span>↗</button>`).join('')||empty(t('Tidak ada pekerjaan aktif','No active work'))}</div>`)}${tracker7(id)}</div>${section7(t('Waktu Pekan Ini','Time This Week'),`<div class="week-bars7">${weeklyValues7(id).map((value,i)=>`<div><b>${value==null?'—':n7(value)+'h'}</b><i style="height:${(value||0)*10}px"></i><small>${t('Sen Sel Rab Kam Jum','Mon Tue Wed Thu Fri').split(' ')[i]}</small></div>`).join('')}</div><p class="scope-note">${t('Contoh pekan 14–18 September · rentang hadir, bukan jam produktif.','Sample week September 14–18 · attendance span, not productive hours.')}</p>`)}</div><aside><div class="photo-story">${portrait(p)}<div class="photo-caption"><button data-action="v5-badge" class="photo-award">${icon('shield')}${t('Kontribusi tercatat','Traceable contribution')}</button><h2>${p.name}</h2></div></div><div class="personal-links7">${btn(t('Data pribadi','Personal details'),'personal',`data-id="${id}"`,'text')}${btn(t('Kontrak kerja','Work contract'),'contract',`data-id="${id}"`,'text')}<small>${t('Bergabung','Joined')} ${date(p.joined)}</small></div>${insight7(true,id)}</aside></div>`;};
function pending7(){return data.leaves.filter(x=>x.status==='pending').length+data.corrections.filter(x=>x.status==='pending').length;}
overview=function(){if(!me().super)return personalOverview(me().id);return pageHead(greeting7(),'')+(pending7()?`<section class="decision7"><h2><span class="pulse"></span>${t('Perlu Keputusan','Needs Your Decision')} · ${pending7()}</h2>${internalApprovals()}</section>`:'')+timeTable7(true)+`<div class="two7">${kpi7(true)}${insight7()}</div>`+curve7(v7.staff)+section7(t('Aktivitas Staf','Staff Activity'),staffEvents().map(e=>`<div class="activity">${avatar(person(e.who))}<div><strong>${person(e.who).name}</strong><p>${esc(L(e.text))}</p><small>${e.time} · ${esc(e.obj)}</small></div></div>`).join('')||empty(t('Belum ada aktivitas pada tanggal ini','No activity on this date')));};
profilePage=function(){const id=me().super?v7.staff:me().id;const previous=state.profile;state.profile=id;const html=base7.profilePage();state.profile=previous;return pageHead(me().super?t('Kinerja Tim','Team Performance'):t('Kinerja Saya','My Performance'),'',periodPicker())+`<div class="two7">${curve7(id)}${kpi7()}</div><details class="panel pad"><summary>${t('Telusuri hasil dan catatan pekerjaan','Explore outcomes and work records')}</summary>${html}</details>`;};
attendancePage=function(){if(me().super){state.attendance='team';if(v3.attendanceTab==='policy')return settingsPage();}let html=base5.attendancePage();const box=document.createElement('div');box.innerHTML=html;if(me().super){box.querySelectorAll('[data-value=mine]').forEach(e=>e.remove());box.querySelectorAll('tbody tr').forEach(tr=>{if(people.filter(p=>p.super).some(p=>tr.textContent.includes(p.name)))tr.remove();});box.querySelectorAll('[data-action=attendance-correction]').forEach(e=>e.remove());}return timeTable7()+box.innerHTML;};
const ruleGuide7={approval:['Permintaan siap diputuskan → tinjau bukti → simpan keputusan','Request ready → review evidence → save decision'],withdraw:['Permintaan → periksa rekening & nominal → verifikasi → catat pembayaran','Request → check account & amount → verify → record payment'],release:['Bahan lengkap → periksa metadata, audio & artwork → hasil pemeriksaan','Complete materials → check metadata, audio & artwork → review outcome'],delivery:['Disetujui → validasi bahan → kirim → simpan bukti pengiriman','Approved → validate materials → send → save delivery evidence'],believe:['Terkirim → menunggu distributor → periksa respons → tindak lanjut','Sent → wait for distributor → check response → follow up'],label:['Minta koreksi → menunggu label → periksa kelengkapan kembali','Request correction → wait for label → recheck completeness']};
const guideSamples7=[0.5,0.7,0.8,1,1.1,1.2,1.4,1.6,1.8,2,2,2.2,2.5,3,4];
function guide7(r,value=r.value){const a=guideSamples7.map(x=>x*(r.id==='believe'?1.5:1)),avg=a.reduce((s,n)=>s+n,0)/a.length,med=a[7],p80=a[11],share=a.filter(x=>x<=value).length/a.length*100;return `<div class="rule-evidence7"><h3>${t('Acuan dari Riwayat Pekerjaan','Reference from Work History')}</h3><p>${t('15 record contoh · bukan hasil audit repo atau data produksi','15 sample records · not a repository audit or production data')}</p><div class="guide-metrics">${[[t('Rata-rata','Average'),avg],[t('Median','Median'),med],['80%',p80]].map(([l,n])=>`<span><small>${l}</small><strong>${n7(n)} ${t('hari','days')}</strong></span>`).join('')}</div><p>${r.mode==='nextday'||r.mode==='monthly'?t('Mengikuti kebijakan tetap; riwayat tidak mengganti aturan ini.','Fixed policy applies; history does not replace it.'):value<med?t('Cenderung ketat: sebagian besar contoh belum selesai pada batas ini.','Tends to be tight: most samples are unfinished at this point.'):value>p80*1.5?t('Cenderung longgar: tindak lanjut mungkin terlambat mendapat perhatian.','Tends to be loose: follow-up may receive attention late.'):t('Cukup seimbang untuk contoh ini. Tinjau kapasitas dan risiko kasus.','Balanced for this sample. Review capacity and case risk.')}</p><small>${n7(share)}% ${t('contoh selesai dalam batas ini. Durasi siap ditangani hingga hasil tahap; waktu menunggu pihak luar dipisahkan. Kapasitas nyata belum terukur.','of samples finish within this limit. From ready-for-action to outcome; external waiting excluded. Actual capacity is not measured.')}</small></div>`;}
workRulesPage=function(){return pageHead(t('Prosedur & Pengingat','Procedures & Reminders'),t('Pahami alurnya, lalu tentukan kapan pekerjaan perlu diperhatikan.','Understand the workflow, then decide when work needs attention.'))+`<div class="notice blue">${t('Peta awal untuk ditinjau. Prosedur produksi belum diverifikasi. Pengingat tidak otomatis mengubah KPI.','Draft map for review. Production procedures are not verified. Reminders do not automatically change KPIs.')}</div><div class="rules7">${data.workRules.map(r=>`<section class="panel pad"><div class="spread"><h2>${L(r.name)}</h2>${btn(t('Atur pengingat','Configure reminder'),'rule-edit',`data-id="${r.id}"`,'small')}</div><p class="route7">${L(ruleGuide7[r.id]||[r.name[0]+' → catat hasil → tahap berikutnya',r.name[1]+' → record outcome → next stage'])}</p><p>${L(r.desc)}</p><div class="rule-active7">${t('Aturan aktif','Active rule')}: <strong>${ruleValue(r)}</strong></div><details><summary>${t('Lihat acuan perhitungan','View calculation guide')}</summary>${guide7(r)}</details></section>`).join('')}</div>`;};
ruleModal=function(id){base7.ruleModal(id);const f=$('form[data-form=work-rule]');f.querySelector('[name=weight]')?.closest('label')?.classList.add('hidden');f.insertAdjacentHTML('beforeend',`<div id="guide-live7">${guide7(data.workRules.find(r=>r.id===id))}</div>`);};
ruleExample=function(){base7.ruleExample();const f=$('form[data-form=work-rule]'),e=$('#guide-live7');if(f&&e){const r=data.workRules.find(x=>x.id===f.dataset.id);e.innerHTML=guide7(r,Number(new FormData(f).get('value'))||r.value);}};
go=function(p,m){if(p!==state.page||m&&m!==state.mode){state.comp='mine';state.attendance=me().super?'team':'mine';v3.attendanceTab='records';v3.peopleTab='people';v6.filter=null;}return base7.go(p,m);};
handleAction=async function(b){const a=b.dataset.action,id=b.dataset.id;if(a==='v6-filter'){v6.filter=v6.filter===id?null:id;render();return;}if(a==='v7-next'||a==='v7-slide'){v7.slide=a==='v7-slide'?Number(id):v7.slide+1;refreshInsights7();return;}if(a==='v7-pause'){v7.paused=!v7.paused;refreshInsights7();return;}if(a==='v7-evidence'){if(state.mode==='platform'){modal(t('Dasar data','Supporting records'),filteredEvidence7());}else modal(t('Dasar wawasan','Insight evidence'),workEvidence(me().super?v7.staff:me().id));return;}if(a==='v7-time-basis'){modal(t('Dasar waktu','Time basis'),`<p>${t('Jam hadir berasal dari masuk–pulang termasuk istirahat. Kurva aktivitas memakai contoh sesi yang terpisah, bukan klik atau status online. Rasio ini bukan skor efisiensi.','Attendance is arrival-to-departure including breaks. Activity uses separate sample sessions, not clicks or online status. This ratio is not an efficiency score.')}</p>`);return;}if(a==='v7-kpi-basis'){modal(t('Dasar KPI simulasi','Simulated KPI basis'),`<p>${t('Kualitas = (hasil − koreksi internal) / hasil. Ketepatan = hasil tepat waktu / hasil. Skor contoh adalah gabungan berbobot keduanya. Hanya record dalam periode terpilih yang dihitung.','Quality = (outcomes − internal corrections) / outcomes. Timeliness = on-time outcomes / outcomes. The sample score combines both with weights. Only selected-period records count.')}</p><p>${t('Skor belum digunakan untuk bonus atau evaluasi resmi. Absensi dan pengingat tidak mengubah bobot ini.','Scores are not used for bonuses or official reviews. Attendance and reminders do not change these weights.')}</p>`);return;}if(a==='nav'&&b.dataset.page==='logs'){modal(t('Riwayat Simulasi','Simulation History'),logsPage());return;}return base7.handleAction(b);};
function filteredEvidence7(){return operationalTasks().map(x=>`<div class="row"><strong>${esc(splitLabel(x.title))}</strong><span>${stageName(x.stage)}</span></div>`).join('')||empty(t('Tidak ada pekerjaan aktif','No active work'));}
function refreshInsights7(){document.querySelectorAll('.insight7').forEach(e=>{e.outerHTML=insight7(Boolean(e.dataset.person),e.dataset.person||me().id);});}
render=function(){base7.render();$('.version-pill').textContent='V7';$('.footer span').textContent='RILIS MUSIK · V7';document.title='Rilis Musik · V7';$('.collapse-side').innerHTML='<span aria-hidden="true">'+(v5.collapsed?'→':'←')+'</span>';document.querySelectorAll('.eyebrow').forEach(e=>{if(/RILIS MUSIK/i.test(e.textContent))e.remove();});if(!$('#scene7'))$('.demo-bar').insertAdjacentHTML('beforeend',`<select id="scene7" aria-label="${t('Konteks pribadi','Personal context')}">${[['normal',t('Hari biasa','Normal day')],['holiday',t('Hari libur','Day off')],['leave',t('Sedang cuti','On leave')]].map(([v,l])=>`<option value="${v}" ${v7.scene===v?'selected':''}>${l}</option>`).join('')}</select>`);};
document.addEventListener('change',e=>{const id=e.target.id,value=e.target.value;if(id==='chart-staff7')v7.staff=value;else if(id==='att-filter7')v7.attFilter=value;else if(id==='att-sort7')v7.attSort=value;else if(id==='att-date7')v7.attDate=value;else if(id==='scene7')v7.scene=value;else if(id==='kpi-weight7')v7.kpiQuality=Number(value);else return;const y=scrollY;render();scrollTo(0,y);});
document.addEventListener('input',e=>{if(e.target.id==='att-search7'){v7.attSearch=e.target.value;const pos=e.target.selectionStart,y=scrollY;render();const f=$('#att-search7');f.focus();f.setSelectionRange(pos,pos);scrollTo(0,y);}});
setInterval(()=>{if(!document.hidden&&!v7.paused&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.querySelector('.insight7:hover,.insight7:focus-within')&&document.querySelector('.insight7')){v7.slide++;refreshInsights7();}},8000);
setInterval(()=>{if($('#live-time7')&&!timeSummary(me().id).complete){const r=timeSummary(me().id);$('#live-time7').textContent=durationLabel(Math.max(0,clockMinutes('14:00')-clockMinutes(r.record?.in||'14:00'))+Math.floor((Date.now()-v7.login)/60000));}},15000);
guide=function(){modal(t('Selamat datang di V7','Welcome to V7'),`<p>${t('Coba lima kartu pekerjaan, panel staf, dan Prosedur & Pengingat. Semua angka dan tindakan tetap simulasi lokal.','Try the five work cards, staff panels and Procedures & Reminders. All figures and actions remain local simulations.')}</p>`);};
