for(const p of people){for(let i=0;i<4;i++){const start=p.id==='adovi'?600:480;const span=Math.round(sampleTime7[p.id].present[i]*60);const hh=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');data.timeRecords[p.id+':2026-09-'+(14+i)]={in:hh(start),out:hh(start+span)};}}
function weeklyValues7(id){return [14,15,16,17,18].map(d=>{const s=timeSummary(id,'2026-09-'+d);return s.complete?s.span/60:null;});}
function payroll7(){const rows=people.map(p=>{const a=payments(p.id);return {p,total:a.reduce((n,x)=>n+x.amount,0),paid:a.filter(x=>x.paid).reduce((n,x)=>n+x.amount,0),bonus:a.filter(x=>x.key==='sales'||x.key?.startsWith('surprise')).reduce((n,x)=>n+x.amount,0)};}),sum=k=>rows.reduce((n,x)=>n+x[k],0),monthly=['2026-07','2026-08'].map(m=>people.reduce((n,p)=>n+payments(p.id,m).reduce((s,x)=>s+x.amount,0),0)),max=Math.max(...monthly,1);return `<div class="payroll-summary7">${[[t('Total Payroll','Total Payroll'),money(sum('total'))],[t('Sudah dibayar','Paid'),money(sum('paid'))],[t('Belum dibayar','Unpaid'),money(sum('total')-sum('paid'))],[t('Penerima lunas','Fully paid recipients'),rows.filter(x=>x.total>0&&x.total===x.paid).length+' / '+rows.length]].map(([l,v])=>`<section class="panel pad"><small>${l}</small><strong>${v}</strong></section>`).join('')}</div><div class="two7">${section7(t('Biaya Payroll Bulanan','Monthly Payroll Cost'),`<div class="volume7">${monthly.map((n,i)=>`<div><div class="volume-bar" style="height:${n/max*115}px"></div><strong>${money(n)}</strong><small>${month(['2026-07','2026-08'][i])}</small></div>`).join('')}</div>`)}${section7(t('Kesiapan Pembayaran','Payment Readiness'),`<strong class="payroll-number7">${money(sum('total')-sum('paid'))}</strong><p>${t('Sisa hak pendapatan pada periode terpilih. Tinjau per staf sebelum mencatat pembayaran.','Outstanding earnings for the selected period. Review each staff member before recording payment.')}</p><p class="scope-note">${t('Penerbitan slip tidak mengubah status pembayaran. Tidak ada pemotongan otomatis berdasarkan jam hadir.','Issuing a slip does not change payment status. Attendance does not cause automatic deductions.')}</p>`)}</div>`;}
compensationPage=function(){const box=document.createElement('div');box.innerHTML=base7.compensationPage();if(me().super&&state.comp==='team')box.querySelector('.tabs')?.insertAdjacentHTML('afterend',payroll7());return box.innerHTML;};
const render7core=render;
render=function(){render7core();$('#main').style.outline='none';document.querySelectorAll('[data-action=nav][data-page=workrules]').forEach(e=>e.remove());const tabs=$('.module-tabs');if(state.page==='module'&&me().super&&destinations.find(d=>d[4].includes(v4.module))?.[0]==='cms')tabs?.insertAdjacentHTML('beforeend',btn(t('Prosedur & Pengingat','Procedures & Reminders'),'nav','data-page="workrules"','text'));if(me().super)$('.demo-bar').insertAdjacentHTML('beforeend',btn(t('Riwayat','History'),'nav','data-page="logs"','text'));document.querySelectorAll('.kpi7 label').forEach(e=>{const d=document.createElement('details');d.innerHTML=`<summary>${t('Uji konfigurasi KPI','Try KPI configuration')}</summary>`;e.before(d);d.append(e);if(d.nextElementSibling?.classList.contains('notice'))d.append(d.nextElementSibling);});if(state.mode==='staff'&&me().super&&state.page==='overview')$('.kpi7')?.insertAdjacentHTML('beforeend',`<div class="kpi-history7">${['2026-07','2026-08'].map(m=>{const list=people.filter(p=>!p.super).map(p=>perf(p.id,m)).filter(p=>p.total),score=list.length?list.reduce((n,x)=>n+(100*(x.total-x.corrections)/x.total*v7.kpiQuality+100*x.on/x.total*(100-v7.kpiQuality))/100,0)/list.length:0;return `<div><i style="height:${score}px"></i><strong>${n7(score)}</strong><small>${month(m)}</small></div>`;}).join('')}</div>`);};
const action7core=handleAction;
handleAction=async function(b){const a=b.dataset.action;if(a==='reset'){if(previewBlocked())return;location.reload();return;}if(a==='v7-evidence'&&state.mode==='staff'){const id=b.dataset.id||me().id;modal(t('Dasar Wawasan','Insight Evidence'),me().super?`<p>${people.filter(p=>!p.super).map(p=>p.name).join(', ')}</p><p>${data.corrections.filter(x=>x.status==='pending').length} ${t('koreksi menunggu','pending corrections')}</p>`:perf(id).items.map(x=>`<div class="row"><strong>${esc(splitLabel(x.title))}</strong><span>${date(x.completed)}</span></div>`).join('')||empty(t('Belum ada bukti periode ini','No evidence for this period')));return;}if(a==='mode'){state.comp='mine';state.attendance=me().super?'team':'mine';v3.attendanceTab='records';v3.peopleTab='people';}return action7core(b);};
