handleAction=async function(b){const a=b.dataset.action;if(a==='v6-metric'&&b.dataset.id==='withdraw'){const d=withdrawalTotals7();modal(t('Penarikan periode ini','Period Withdrawals'),`<div class="row"><span>${t('Permintaan','Requests')}</span><strong>${money(d.total)}</strong></div><div class="row"><span>${t('Sudah dibayar','Paid')}</span><strong>${money(d.paid)}</strong></div><div class="row"><span>${t('Belum dibayar','Unpaid')}</span><strong>${money(d.unpaid)}</strong></div><p>${t('75 juta sudah dibayar pada awal simulasi; sisa terhubung dengan dua penarikan di antrean. Periode pembanding 120 juta.','75 million is paid at simulation start; the remainder is linked to two queued withdrawals. Comparison period: 120 million.')}</p>`);return;}if(a==='mode'||a==='v5-collapse'){const before=$('.side5').getBoundingClientRect().width;await action7finished(b);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){if(a==='v5-collapse'){const after=$('.side5').getBoundingClientRect().width;$('.side5').animate([{width:before+'px'},{width:after+'px'}],{duration:350,easing:'ease'});$('.shell').animate([{marginLeft:before+'px'},{marginLeft:after+'px'}],{duration:350,easing:'ease'});}else{const el=$('.side-mode .mode-switch');el.animate([{opacity:.55,transform:'scale(.96)'},{opacity:1,transform:'scale(1)'}],{duration:280,easing:'ease-out'});}}return;}return action7finished(b);};
