const dashboard7global=dashboard;
dashboard=function(){const b=document.createElement('div');b.innerHTML=dashboard7global();const s=b.querySelector('.task-stats6'),tasks=data.tasks.filter(x=>x.stage!=='done'),ops=data.ops.filter(x=>['pending','approved'].includes(x.status)),total=tasks.length+ops.length,q=tasks.filter(x=>x.stage==='queued').length+ops.filter(x=>x.status==='pending').length;if(s){s.querySelector(':scope>small').textContent=t('Global · seluruh pekerjaan aktif; rincian tetap mengikuti akses','Global · all active work; detail access remains restricted');s.querySelector(':scope>strong').textContent=total;s.querySelector('.tick-track').innerHTML=Array.from({length:50},(_,i)=>`<i class="${i/50<(total?q/total:0)?'queued':'handling'}"></i>`).join('');s.querySelector('.tick-track').setAttribute('aria-label',`${q} ${t('antrean','queued')}, ${total-q} ${t('dalam penanganan','in progress')}`);s.querySelector('.legend').innerHTML=`<span>${q} ${t('Antrean','Queued')}</span><span>${total-q} ${t('Dalam penanganan','In progress')}</span>`;}return b.innerHTML;};

